import { setupTest } from "ember-qunit";
import { module, test } from "qunit";
import { cook } from "discourse/lib/text";

module("lib:details-cooked-test", (hooks) => {
  setupTest(hooks);

  test("AI-generated details", async function (assert) {
    const cooked = await cook(
      '[details="<Summary>" ai]\nHidden text\n[/details]'
    );
    assert.strictEqual(
      cooked.toString(),
      '<details class="ai-quote">\n<summary>\n<span>&lt;Summary&gt;</span><span class="ai-badge" data-ai-label="AI" title="This content has been partially or fully generated by AI"></span></summary>\n<p>Hidden text</p>\n</details>',
      "cooked details show the AI badge and escape the summary"
    );

    const withValue = await cook(
      '[details="Summary" ai=true]\nHidden text\n[/details]'
    );
    assert.strictEqual(
      withValue.toString(),
      "<details>\n<summary>\nSummary</summary>\n<p>Hidden text</p>\n</details>",
      "only the bare flag applies the label"
    );
  });

  test("details badge matches core badge attributes", async function (assert) {
    const cooked = await cook('[details="Title" ai]\nHidden text\n[/details]');
    const doc = new DOMParser().parseFromString(cooked.toString(), "text/html");
    const badge = doc.querySelector("details > summary > .ai-badge");

    assert.true(!!badge, "the summary contains the shared badge class");
    // Keep in sync with frontend/discourse-markdown-it/src/ai-badge.js.
    assert.deepEqual(
      badge?.getAttributeNames().sort(),
      ["class", "data-ai-label", "title"],
      "the details badge has exactly the core badge attributes"
    );
    assert.strictEqual(
      badge?.getAttribute("data-ai-label"),
      "AI",
      "the label is present"
    );
    assert.true(!!badge?.getAttribute("title"), "the badge has a tooltip");
    assert.strictEqual(badge?.textContent, "", "the label comes from CSS");
  });

  test("details", async (assert) => {
    const testCooked = async (input, expected, text) => {
      const cooked = (await cook(input)).toString();
      assert.strictEqual(cooked, expected, text);
    };

    await testCooked(
      `<details><summary>Info</summary>coucou</details>`,
      `<details><summary>Info</summary>coucou</details>`,
      "manual HTML for details"
    );

    await testCooked(
      `[details=test'ing all the things]\ntest\n[/details]`,
      `<details>\n<summary>\ntest'ing all the things</summary>\n<p>test</p>\n</details>`,
      "details with spaces and a single quote"
    );

    await testCooked(
      `[details=”test'ing all the things”]\ntest\n[/details]`,
      `<details>\n<summary>\ntest'ing all the things</summary>\n<p>test</p>\n</details>`,
      "details surrounded by finnish double quotes"
    );
  });
});
